下面程序运行后输出的 `copies` 是多少？请说明每个函数调用是否产生拷贝。
```cpp
#include <cstdio>

struct Counted {
    static inline int copies = 0;
    Counted() = default;
    Counted(const Counted&) { ++copies; }
};

void byValue(Counted) {}
void byRef(Counted&) {}
void byConstRef(const Counted&) {}

int main() {
    Counted c;
    byValue(c);
    byRef(c);
    byConstRef(c);
    std::printf("copies=%d\n", Counted::copies);
}
```

